formulas.expression:
if(
{!var_PDQuantityv2} > 1,
LEFT(
"Multi Product - Performance Data"+" | "+text({!recordId.Type})+" | "+text({!recordId.Amount}) + " " +text({!recordId.CurrencyIsoCode})+" | "+{!recordId.Account_Name__c}+" | "+{!recordId.Primary_Contact__r.FirstName}+" "+{!recordId.Primary_Contact__r.LastName},120),

LEFT({!var_productname}+" | "+text({!recordId.Type})+" | "+{!recordId.Account_Name__c}+" | "+text({!recordId.Amount}) + " " +text({!recordId.CurrencyIsoCode})+" | "+{!recordId.Primary_Contact__r.FirstName}+" "+{!recordId.Primary_Contact__r.LastName},120)
)

if(
{!var_TotalRecords}>1 && text({!recordId.Purchased_Via__c}) != 'Agency',
LEFT("GXRs - Multi Line Sub" & " | " & TEXT({!recordId.Type}) & " | " & text({!recordId.Current_Deal_Length__c})&" Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},120),
if(
{!var_TotalRecords}>1 && text({!recordId.Purchased_Via__c}) == 'Agency',
LEFT("GXRs - Multi Line Sub" & " | " & TEXT({!recordId.Type}) & " | " & text({!recordId.Current_Deal_Length__c})&" Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.End_User_Account__r.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},120),
if(
text({!recordId.Purchased_Via__c}) == 'Agency',
LEFT({!var_productname} & " | " & TEXT({!recordId.Type}) & " | " & text({!recordId.Current_Deal_Length__c}) & " Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.End_User_Account__r.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},120),
LEFT({!var_productname} & " | " & TEXT({!recordId.Type}) & " | " & text({!recordId.Current_Deal_Length__c}) & " Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},120)
)
)
)

LEFT(
if(
{!var_TotalRecords}>1 && text({!recordId.Purchased_Via__c}) !='Agency',
"GXRs - Multi Line Sub" & " | " & TEXT({!recordId.Type}) & " | " & ({!recordId.Budget_Renewal_Month__c}) & " | "  & text({!recordId.Current_Deal_Length__c})&" Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
if(
{!var_TotalRecords}>1 && text({!recordId.Purchased_Via__c}) =='Agency',
"GXRs - Multi Line Sub" & " | " & TEXT({!recordId.Type}) & " | " & ({!recordId.Budget_Renewal_Month__c}) & " | "  & text({!recordId.Current_Deal_Length__c})&" Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.End_User_Account__r.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
if(
text({!recordId.Purchased_Via__c}) =='Agency',
{!var_productname} & " | " & TEXT({!recordId.Type}) & " | " & ({!recordId.Budget_Renewal_Month__c}) & " | "  &
text({!recordId.Current_Deal_Length__c}) & " Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.End_User_Account__r.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
{!var_productname} & " | " & TEXT({!recordId.Type}) & " | " & ({!recordId.Budget_Renewal_Month__c}) & " | "  &
text({!recordId.Current_Deal_Length__c}) & " Months | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " &  {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName}
)
)
),120)

IF(
    AND(
        {!var_TotalRecords} > 1,
        OR(
            TEXT({!recordId.Type}) = 'Renewal',
            TEXT({!recordId.Type}) = 'Auto-Renewal'
        )
    ),
    LEFT(
        "Docket Navigator - Multi Product | " & TEXT({!recordId.Type}) & " | " & {!recordId.Budget_Renewal_Month__c} & " | " & TEXT({!recordId.Current_Deal_Length__c}) & " Month(s) | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " & {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
        120
    ),
    IF(
        AND(
            {!var_TotalRecords} > 1,
            NOT(
                OR(
                    TEXT({!recordId.Type}) = 'Renewal',
                    TEXT({!recordId.Type}) = 'Auto-Renewal'
                )
            )
        ),
        LEFT(
            "Docket Navigator - Multi Product | " & TEXT({!recordId.Type}) & " | " & TEXT({!recordId.Current_Deal_Length__c}) & " Month(s) | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " & {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
            120
        ),
        IF(
            NOT(
                OR(
                    TEXT({!recordId.Type}) = 'Renewal',
                    TEXT({!recordId.Type}) = 'Auto-Renewal'
                )
            ),
            LEFT(
                {!var_productname} & " | " & TEXT({!recordId.Type}) & " | " & TEXT({!recordId.Current_Deal_Length__c}) & " Month(s) | " & TEXT({!var_QLquantity}) & " Users | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " & {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
                120
            ),
            LEFT(
                {!var_productname} & " | " & TEXT({!recordId.Type}) &  " | " & {!recordId.Budget_Renewal_Month__c} &" | " & TEXT({!recordId.Current_Deal_Length__c}) & " Month(s) | " & TEXT({!var_QLquantity}) & " Users | " & TEXT({!recordId.CurrencyIsoCode}) & " | " & TEXT({!recordId.Amount}) & " | " & {!recordId.Account.Name} & " | " & {!recordId.Primary_Contact__r.FirstName} & " " & {!recordId.Primary_Contact__r.LastName},
                120
            )
        )
    )
)

if({!var_TotalRecords}>1,

LEFT(text(YEAR({!recordId.CloseDate}))+" | "+" LCG"+" | "+"LPI"+" | "+" Subs Package"+" | "+{!recordId.Account_Name__c}+" | "+{!recordId.Primary_Contact__r.FirstName}+" "+{!recordId.Primary_Contact__r.LastName},120),

LEFT(text(YEAR({!recordId.CloseDate}))+" | "+" LCG"+" | "+"LPI"+" | "+ {!var_productname}+" | "+{!recordId.Account_Name__c}+" | "+{!recordId.Primary_Contact__r.FirstName}+" "+{!recordId.Primary_Contact__r.LastName},120)

)
